#!/usr/bin/env node
/**
 * The `agent-sdk` CLI entry point. Every command is declared once in
 * `internal/cli/commands/`, which also produces `--help` and
 * `agent-sdk help --json`. Run `agent-sdk` for the command index.
 */
import { registerAuthoredModuleLoaders } from "../internal/authored-loaders.js";
import { COMMANDS } from "../internal/cli/commands/index.js";
import { isHelpRequest, runCli } from "../internal/cli/dispatch.js";
import { askOnTty, writeStdout } from "../internal/cli/io.js";
import { formatCliVersion } from "../internal/distribution.js";
import { isServeRestartWorker } from "../internal/serve-restart.js";
import { flushSessionRunFatal } from "../internal/session-run-log.js";
import { warnIfOutdated } from "../internal/update-check.js";
/** Commands that skip the update notice: `update` checks itself, and `mcp` owns stdout. */
const NO_UPDATE_NOTICE = new Set(["update", "mcp"]);
async function main(argv) {
    const [command, ...rest] = argv;
    if (command === "--version" || command === "-V") {
        await writeStdout(formatCliVersion({ json: rest.includes("--json") }));
        return 0;
    }
    // Best-effort, cached, and silent on failure. --json runs stay quiet for
    // machine consumers. Help runs skip it, so the hosting probe of
    // `agent-sdk --help` never waits on the registry.
    if (command !== undefined &&
        !isHelpRequest(argv) &&
        !NO_UPDATE_NOTICE.has(command) &&
        !rest.includes("--json") &&
        !isServeRestartWorker()) {
        await warnIfOutdated();
    }
    return runCli(COMMANDS, argv, {
        stdout: writeStdout,
        stderr: (text) => void process.stderr.write(text),
        ask: askOnTty,
    });
}
/**
 * The Cursor SDK's Connect/HTTP2 client sometimes emits uncaught stream
 * or TLS errors (notably `NGHTTP2_FRAME_SIZE_ERROR` on large shell/tool
 * payloads, and mid-handshake socket disconnects) outside the promise
 * `run.wait()` returns. Without a listener the unhandled rejection exits
 * the whole agent-serve process with code 1. Swallow those transport
 * failures so turns can fail cleanly and the server stays up.
 */
function installTransportErrorGuards() {
    const isTransportNoise = (reason) => {
        const message = reason instanceof Error ? `${reason.message}\n${reason.stack ?? ""}` : String(reason);
        const code = reason !== null &&
            typeof reason === "object" &&
            "code" in reason &&
            typeof reason.code === "string"
            ? reason.code
            : undefined;
        return (code === "ERR_HTTP2_STREAM_ERROR" ||
            code === "ECONNRESET" ||
            code === "ECONNREFUSED" ||
            code === "EPIPE" ||
            code === "ETIMEDOUT" ||
            code === "ENOTFOUND" ||
            code === "EAI_AGAIN" ||
            message.includes("NGHTTP2_FRAME_SIZE_ERROR") ||
            message.includes("Stream closed with error code") ||
            message.includes("Client network socket disconnected before secure TLS connection was established") ||
            message.includes("socket hang up") ||
            message.includes("other side closed"));
    };
    const log = (label, reason) => {
        const text = reason instanceof Error ? reason.message : String(reason);
        process.stderr.write(`[bdk] ${label} (server stays up): ${text.slice(0, 400)}\n`);
    };
    process.on("unhandledRejection", (reason) => {
        if (isTransportNoise(reason)) {
            log("swallowed unhandledRejection", reason);
            return;
        }
        log("unhandledRejection", reason);
    });
    process.on("uncaughtException", (error) => {
        if (isTransportNoise(error)) {
            log("swallowed uncaughtException", error);
            return;
        }
        process.stderr.write(`[bdk] uncaughtException: ${error.stack ?? error.message}\n`);
        void flushSessionRunFatal(error).finally(() => {
            process.exit(1);
        });
    });
}
installTransportErrorGuards();
// Authored agent files are TypeScript imported at runtime; install the tsx
// loader (and the framework import aliases on compiled runs) before any
// command touches a project. In-repo CLI is `bin/agent-serve.ts`.
registerAuthoredModuleLoaders()
    .then(() => main(process.argv.slice(2)))
    .then((code) => {
    // Ephemeral run/eval can leave SDK/HTTP handles open; force exit. Exit
    // only after stdout drains: a pipe write is async, so an early exit cuts
    // a --json payload at the pipe buffer (8 KiB under a Node parent).
    process.stdout.write("", () => process.exit(code));
}, (error) => {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exit(1);
});
